import React, { useState } from 'react';
import './App.css';

function App() {
  const [menu, setMenu] = useState([
    { name: 'Café Express', price: 2.5, selected: false },
    { name: 'Cappuccino', price: 3.0, selected: false },
    { name: 'Thé Vert', price: 2.0, selected: false },
    { name: 'Jus d\'orange', price: 3.5, selected: false },
  ]);

  const toggleItem = (index) => {
    const updated = [...menu];
    updated[index].selected = !updated[index].selected;
    setMenu(updated);
  };

  const accept = () => {
    const selected = menu.filter(m => m.selected).map(m => m.name).join(', ');
    alert(`Vous avez choisi : ${selected}`);
  };

  const callWaiter = () => {
    alert("Le serveur arrive !");
  };

  return (
    <div className="App">
      <h1>☕ Bienvenue au Café</h1>
      <ul>
        {menu.map((item, idx) => (
          <li key={idx}>
            <label>
              <input type="checkbox" checked={item.selected} onChange={() => toggleItem(idx)} />
              {item.name} - {item.price} €
            </label>
          </li>
        ))}
      </ul>
      <button onClick={accept}>✅ Accepter</button>
      <button onClick={callWaiter}>🔔 Appeler le serveur</button>
    </div>
  );
}

export default App;
